// 1. Captura a resposta do nó anterior usando a sintaxe recomendada do N8N
const responseData = $input.first().json;

// 2. Navega pela estrutura do JSON para pegar o Base64 do áudio
const base64Audio = $('Gerar Áudio com GOOGLE GEMINI').first().json.candidates[0].content.parts[0].inlineData.data
const pcmBuffer = Buffer.from(base64Audio, 'base64');

// 3. Configurações do áudio nativo do Gemini TTS
const sampleRate = 24000;
const numChannels = 1;
const bitsPerSample = 16;

// 4. Cria o cabeçalho WAV de 44 bytes
const wavHeader = Buffer.alloc(44);
const blockAlign = numChannels * (bitsPerSample / 8);
const byteRate = sampleRate * blockAlign;
const dataLength = pcmBuffer.length;

wavHeader.write('RIFF', 0);                          // ChunkID
wavHeader.writeUInt32LE(36 + dataLength, 4);         // ChunkSize
wavHeader.write('WAVE', 8);                          // Format
wavHeader.write('fmt ', 12);                         // Subchunk1ID
wavHeader.writeUInt32LE(16, 16);                     // Subchunk1Size (16 para PCM)
wavHeader.writeUInt16LE(1, 20);                      // AudioFormat (1 para PCM não comprimido)
wavHeader.writeUInt16LE(numChannels, 22);            // NumChannels
wavHeader.writeUInt32LE(sampleRate, 24);             // SampleRate
wavHeader.writeUInt32LE(byteRate, 28);               // ByteRate
wavHeader.writeUInt16LE(blockAlign, 32);             // BlockAlign
wavHeader.writeUInt16LE(bitsPerSample, 34);          // BitsPerSample
wavHeader.write('data', 36);                         // Subchunk2ID
wavHeader.writeUInt32LE(dataLength, 40);             // Subchunk2Size

// 5. Junta o cabeçalho criado com os dados brutos de áudio do Gemini
const wavBuffer = Buffer.concat([wavHeader, pcmBuffer]);

// 6. Retorna no formato binário padrão que o N8N reconhece como player de áudio
return [
  {
    json: {
      status: "Sucesso",
      mensagem: "Áudio WAV gerado pronto para reprodução!"
    },
    binary: {
      data: {
        data: wavBuffer.toString('base64'),
        mimeType: 'audio/wav',
        fileName: 'assistente_gemini.wav'
      }
    }
  }
];

// 1. Pega todos os itens que entraram no nó
const todosOsItens = $input.all();
const totalTemplates = todosOsItens.length; 

let tempoAcumulado = 0;
let indicesSorteados = [];
let videosSorteados = [];
const alvoSegundos = 60;

while (indicesSorteados.length < totalTemplates && tempoAcumulado < $('Tamanho').first().json.duracaoEmSegundos) {
  const indiceAleatorio = Math.floor(Math.random() * totalTemplates);

  if (indicesSorteados.indexOf(indiceAleatorio) === -1) {
    const itemEstrategico = todosOsItens[indiceAleatorio].json;
    const duracaoVideo = itemEstrategico.tv_duracao; // 
    tempoAcumulado += duracaoVideo;
    indicesSorteados.push(indiceAleatorio);
    videosSorteados.push(itemEstrategico);    
  }  
}

return [
  {
    json: {
      status: "Sucesso",
      tempoTotalGerado: tempoAcumulado,
      quantidadeClipes: videosSorteados.length,
      videos: videosSorteados
    }
  }
];

